/**
 * Calculates the product sign of an array of integers.
 *
 * The product sign is defined as the sum of the products of the prime factors of each number,
 * where each prime factor is either added or subtracted depending on whether the number appears
 * an even or odd number of times in the array.
 *
 * @param array $arr The input array of integers.
 * @return int|null The product sign of the input array, or null if the array is empty or contains no prime numbers.
 */
function prod_signs(array $arr): ?int
{
    // Define a helper function to check if a number is prime.
    /**
     * Checks if a number is prime.
     *
     * A prime number is a natural number greater than 1 that has no positive divisors other than 1 and itself.
     *
     * @param int $n The number to check.
     * @return bool True if the number is prime, false otherwise.
     */
    function is_prime(int $n): bool
    {
        if ($n < 2) {
            return false;
        }
        for ($i = 2; $i <= sqrt($n); $i++) {
            if ($n % $i == 0) {
                return false;
            }
        }
        return true;
    }

    // Find all unique prime numbers in the input array.
    $primes = array_filter($arr, function ($x) use ($arr) {
        return is_prime(abs($x)) && array_unique($arr) === $arr;
    });

    // If there are no prime numbers in the array, return null.
    if (empty($primes)) {
        return null;
    }

    // Calculate the product sign by summing the products of the prime factors of each number.
    // If a number appears an even number of times, add its product; otherwise, subtract it.
    return array_sum(array_map(function ($x) use ($arr) {
        return $x * ($arr[$x] % 2 === 0 ? 1 : -1);
    }, $primes));
}
